<script setup lang="ts">
import{computed,ref,watch,useId}from'vue';
import type{Unit,WarState,CommandUnit}from'../types';
import{militarySvg,unitSymbolId}from'../militarySymbols';
import{personnelStrengthPct}from'../personnelProjection';
import{weaponLimits}from'../weaponRanges';
import{parameterRows,filterParameters,parameterValue,equipmentUnavailablePct,physicalFormationValues,unitParameterContext}from'../unitParameters';
import ParameterIcon from'./ParameterIcon.vue';
const props=defineProps<{unit:Unit|null;world:WarState;team:string;turn:number;command?:CommandUnit;busy?:boolean;readOnly?:boolean;agent?:boolean;symbolId?:string}>();
const emit=defineEmits<{'prepare-order':[action:string];language:[]}>();
const active=ref('overview'),query=ref(''),shown=ref(50),id=useId();
const tabs=[{id:'overview',label:'概览'},{id:'people',label:'人员'},{id:'equipment',label:'装备'},{id:'fire',label:'火力'},{id:'logistics',label:'保障'},{id:'command',label:'指挥'},{id:'source',label:'史料'},{id:'all',label:'全部'}];
watch([()=>props.unit?.name,()=>props.team],()=>{active.value='overview';query.value='';shown.value=50;});
watch(query,()=>{shown.value=50});
const unit=computed(()=>props.unit),f=computed(()=>props.unit?.formation),p=computed(()=>props.unit?.personnel);
const physical=computed(()=>physicalFormationValues(props.unit?.formation));
const number=(value:unknown,unit='')=>typeof value==='number'&&Number.isFinite(value)?`${value.toLocaleString('zh-CN',{maximumFractionDigits:3,useGrouping:false})}${unit}`:'未记录';
const value=(item:unknown)=>parameterValue(item);
const peopleValue=(key:string)=>props.unit?.personnel?.[key as keyof NonNullable<Unit['personnel']>];
const strength=computed(()=>props.unit?personnelStrengthPct(props.unit):null);
const ranges=computed(()=>props.unit?weaponLimits(props.world,props.unit):{});
const parameterContext=computed(()=>unitParameterContext(props.world,props.unit,props.command));
const node=computed(()=>parameterContext.value.supply_node),campaignActor=computed(()=>parameterContext.value.campaign_actor);
const parentName=computed(()=>props.world.historical_initial?.definition.units.find(u=>u.id===props.unit?.parent_id)?.name??props.unit?.parent_id);
const mode=computed(()=>props.world.history_replay?'史料事件参考':props.world.dsh_execution?'DSH模型估计':props.world.afsim?.experimental_continuous?'AFSIM连续机动验证模式':props.world.afsim?'AFSIM执行后态势':'已提交初态配置');
const all=computed(()=>parameterRows(parameterContext.value));
const sourceRows=computed(()=>props.unit?parameterRows({personnel:props.unit.personnel,equipment:props.unit.equipment,parameter_sources:props.unit.parameter_sources,historical_evidence:props.unit.historical_evidence,historical_reference:props.unit.historical_reference,historical_facts:props.unit.historical_facts,frame_evidence_status:props.unit.frame_evidence_status}).filter(r=>/source|evidence|reference|assumption|scope|historical_facts/.test(r.path)):[]);
const coordinate=(n:unknown)=>typeof n==='number'&&Number.isFinite(n)?n.toFixed(6)+'°':'未记录';
const filtered=computed(()=>filterParameters(all.value,query.value));
const equipped:Record<string,string>={armor:'装甲车辆',artillery:'火炮',air_defense:'防空装备',engineer:'工兵作业组',transport:'运输单元'};
const actions=[{id:'move',label:'规划移动',icon:'move'},{id:'fire',label:'规划攻击',icon:'fire'},{id:'bombard',label:'规划炮击',icon:'fire'},{id:'resupply',label:'安排补给',icon:'logistics'},{id:'recon',label:'安排侦察',icon:'overview'}];
const canPrepare=computed(()=>!props.busy&&!props.readOnly&&props.command?.controllable&&props.command?.capabilities.enabled);
function keyboard(event:KeyboardEvent,index:number){let next=index;if(event.key==='ArrowRight')next=(index+1)%tabs.length;else if(event.key==='ArrowLeft')next=(index+tabs.length-1)%tabs.length;else if(event.key==='Home')next=0;else if(event.key==='End')next=tabs.length-1;else return;event.preventDefault();active.value=tabs[next]!.id;(event.currentTarget as HTMLElement).parentElement?.querySelectorAll<HTMLButtonElement>('[role=tab]')[next]?.focus();}
</script>
<template>
 <section class="unit-inspector" data-testid="unit-inspector" aria-label="选中单位完整参数">
  <p v-if="!unit" role="status">当前名单中没有唯一匹配的单位，请重新选择；不会用初始编制代替当前单位。</p>
  <template v-else>
   <div class="identity"><span class="unit-symbol" v-html="militarySvg(symbolId??unitSymbolId(unit),team)"/><div><span class="eyebrow">{{team==='red'?'红方':team==='blue'?'蓝方':'参考单位'}} · {{unit.echelon??'层级未记录'}}</span><h3>{{unit.name}}</h3><p>{{unit.type??'兵种未记录'}}<span v-if="parentName"> · 上级 {{parentName}}</span></p></div></div>
   <p class="observation" data-testid="unit-observation-scope">T+{{turn}} · {{world.current_time??'时刻未记录'}} · {{mode}}。数量和部署的史实／估计依据见“史料”。</p>
   <nav v-if="!readOnly&&command" class="unit-quick-actions" aria-label="单位操作快捷入口"><button v-for="a in actions.filter(a=>command?.capabilities.actions.includes(a.id))" :key="a.id" type="button" :disabled="!canPrepare" @click="emit('prepare-order',a.id)"><ParameterIcon :name="a.icon"/>{{a.label}}</button><button type="button" :disabled="!canPrepare" @click="emit('language')"><ParameterIcon name="command"/>自然语言下令</button><small>先准备命令，确认入队后下一轮执行。</small></nav>
   <div class="unit-tabs" role="tablist" aria-label="单位参数类别"><button v-for="(tab,index) in tabs" :id="id+'-'+tab.id" :key="tab.id" type="button" role="tab" :aria-selected="active===tab.id" :aria-controls="id+'-content'" :tabindex="active===tab.id?0:-1" @click="active=tab.id" @keydown="keyboard($event,index)"><ParameterIcon :name="tab.id"/><span>{{tab.label}}</span></button></div>
   <div :id="id+'-content'" role="tabpanel" :aria-labelledby="id+'-'+active" class="unit-tab-body" tabindex="0">
    <template v-if="active==='overview'">
     <div class="metrics"><div><ParameterIcon name="people"/><span>现有人员</span><strong>{{number(p?.current,' 人')}}</strong><small>累计投入 {{number(p?.committed,' 人')}}</small></div><div><ParameterIcon name="shield"/><span>人员保有率</span><strong>{{number(strength,'%')}}</strong><small>现有／累计投入，非满编率</small></div><div><ParameterIcon name="clock"/><span>疲劳／压制</span><strong><span data-testid="unit-fatigue-value">{{number(physical.fatigue)}}</span> / {{number(f?.suppression)}}</strong><small>模型状态分值</small></div><div><ParameterIcon name="logistics"/><span>粮食／通用弹药</span><strong>{{number(unit.logistics?.food)}} / {{number(unit.logistics?.ammo)}}</strong><small>模型工作量，非吨数／发数</small></div><div><ParameterIcon name="fire"/><span>炮弹库存</span><strong>{{number(f?.shells,' 发')}}</strong><small>装填 {{f?.reload_remaining_s===undefined?'旧周期 '+number(f?.reload_remaining):number(f.reload_remaining_s,' 秒')}}</small></div><div><ParameterIcon name="command"/><span>联络／情报可信度</span><strong>{{number(f?.signal)}} / {{number(f?.intel_confidence)}}</strong><small>情报年龄 {{number(f?.intel_age_min,' 分钟')}}</small></div></div>
     <dl class="parameters"><dt>状态指数／士气</dt><dd>{{value(unit.hp)}} / {{value(unit.morale)}}</dd><dt>当前位置</dt><dd>{{coordinate(unit.lat)}}, {{coordinate(unit.lng)}}</dd><dt>配置速度</dt><dd>{{number(unit.speed,' km/h')}}</dd><dt>本轮可移动上限</dt><dd>{{number(command?.capabilities.move_km,' km')}}</dd><dt>参与状态</dt><dd>{{command?.capabilities.participation?.label??command?.capabilities.arrival?.status??'未记录'}}</dd></dl>
     <p v-if="command?.capabilities.reason" class="scope-note">{{command.capabilities.reason}}</p>
    </template>
    <template v-else-if="active==='people'"><h4>人员连续账 <small>单位：人</small></h4><dl class="parameters"><template v-for="[key,label] in [['committed','累计投入'],['current','现有可用'],['casualties','累计战斗减员'],['killed','阵亡'],['wounded','负伤'],['missing','失踪'],['captured','被俘'],['unclassified_casualties','未分类减员'],['noncombat_losses','非战斗损失']]" :key="key"><dt>{{label}}</dt><dd>{{number(peopleValue(key!))}}</dd></template></dl><p class="scope-note">战斗减员包括阵亡、负伤等分类；缺载不按0计算。{{unit.personnel?.breakdown_source}}</p></template>
    <template v-else-if="active==='equipment'"><h4>分类装备连续账</h4><div class="table-scroll"><table><caption>投入、可用、受损与损毁数量</caption><thead><tr><th>装备</th><th>投入</th><th>可用</th><th>受损</th><th>损毁</th><th>不可用率</th></tr></thead><tbody><tr v-for="(e,index) in unit.equipment" :key="index"><th scope="row" :title="e.name">{{equipped[e.category??'']??e.name}}</th><td>{{number(e.committed)}}</td><td>{{number(e.operational)}}</td><td>{{number(e.damaged)}}</td><td>{{number(e.destroyed)}}</td><td>{{number(equipmentUnavailablePct(e),'%')}}</td></tr></tbody></table></div><p v-if="!unit.equipment?.length">装备分类未记录，不推定为零装备。</p><p class="scope-note">不可用率＝（受损＋损毁）／累计投入，包含历轮积累，不是本轮战损率。计数缺载或不平衡时不计算。完整名称、单位及来源见“全部”。</p></template>
    <template v-else-if="active==='fire'"><h4>火力与防护</h4><dl class="parameters"><template v-for="(range,key) in ranges" :key="key"><dt>{{key==='fire'?'直射':key==='bombard'?'炮击':key==='suppress'?'压制':'防空'}}范围</dt><dd>{{number(range.min_range_m)}}—{{number(range.max_range_m,' m')}}</dd></template><dt>展开面积</dt><dd>{{number(f?.dispersion_km2,' km²')}}</dd><dt>工事分值</dt><dd>{{number(f?.entrenchment)}}</dd><dt>防护系数</dt><dd>{{number(f?.protection)}}</dd><dt>炮弹</dt><dd>{{number(f?.shells,' 发')}}</dd><dt>防空弹药</dt><dd>{{number(f?.aa_rounds,' 发')}}</dd><dt>装填余时</dt><dd>{{number(f?.reload_remaining_s,' 秒')}}</dd></dl><p class="scope-note">标称射程来自本局配置；实际开火还受弹药、联络、地形和目标可用性约束。</p><details v-if="campaignActor" class="fortification-state" data-testid="unit-fortification-state"><summary><ParameterIcon name="shield"/>工事明细<span v-if="campaignActor.fortification_components?.length"> · {{campaignActor.fortification_components.length}}组参数</span></summary><dl class="parameters"><dt>工事基准下限</dt><dd>{{number(campaignActor.base_entrenchment)}}</dd><dt>工事完整度下限</dt><dd>{{number(campaignActor.fortification_integrity,'%')}}</dd><dt>原始防护系数</dt><dd>{{number(campaignActor.base_protection)}}</dd></dl><div v-if="campaignActor.fortification_components?.length" class="table-scroll"><table><caption>保留的工事分组参数</caption><thead><tr><th>组别</th><th>工事基准</th><th>完整度</th></tr></thead><tbody><tr v-for="(part,index) in campaignActor.fortification_components" :key="index"><th scope="row">第{{index+1}}组</th><td>{{number(part.base_entrenchment)}}</td><td>{{number(part.fortification_integrity,'%')}}</td></tr></tbody></table></div><p class="scope-note">各组记录合兵后保留的不同工事状态，不代表额外兵力。基准与完整度成对使用；当前工事分值和防护系数以上方执行结果为准。</p></details><details v-if="f?.last_execution"><summary>最近执行回执 · T+{{f.last_execution.turn??'未知'}}</summary><p v-if="Number(f.last_execution.turn)!==turn">这是先前回合的记录。</p><dl class="parameters"><template v-for="row in parameterRows(f.last_execution)" :key="row.path"><dt>{{row.label}}</dt><dd>{{value(row.value)}}</dd></template></dl></details></template>
    <template v-else-if="active==='logistics'"><h4>随队库存与保障</h4><dl class="parameters"><template v-for="[key,label,suffix] in [['food','粮食','工作量'],['ammo','通用弹药','工作量']]" :key="key"><dt>{{label}}</dt><dd>{{number(unit.logistics?.[key as 'food'|'ammo'],' '+suffix)}}</dd></template><dt>燃油</dt><dd data-testid="unit-fuel-value">{{number(physical.fuel_liters,' 升')}}<small v-if="physical.precision==='physical'"> · 含小数余量</small></dd><dt>备件</dt><dd>{{number(f?.spares,' 件')}}</dd><dt>工程耗材</dt><dd>{{number(f?.materials,' 包')}}</dd><dt>绑定补给点</dt><dd>{{node?.name??unit.supply_node_id??'未记录'}}</dd><dt>补给点剩余工作量</dt><dd>{{number(node?.stock)}}</dd></dl><p class="scope-note">归一化工作量与实物库存分别记账；补给点有库存不表示运输线路畅通或已收到补给。</p></template>
    <template v-else-if="active==='command'"><h4>指挥与机动条件</h4><dl class="parameters"><dt>DSH单位智能体</dt><dd>{{agent===undefined?'未读取':agent?'已启用':'未启用'}}</dd><dt>指挥权限</dt><dd>{{readOnly?'只读':command?.controllable?'当前可指挥':'当前不可指挥'}}</dd><dt>机动方式</dt><dd>{{f?.motorized===undefined?'未明确记录':f.motorized?'摩托化':'非摩托化'}}</dd><dt>机动依据</dt><dd>{{command?.capabilities.movement_basis??'未读取命令观测'}}</dd><dt>不支持的行动</dt><dd>{{command?.capabilities.unsupported.join('、')||'未记录'}}</dd></dl></template>
    <template v-else-if="active==='source'"><h4>史料与参数依据</h4><p v-if="!sourceRows.length" role="status">本单位没有单独的参数来源记录。</p><p class="scope-note">历史番号有来源，不代表本局人数、配发或位置已考证。历史档案统计不是当前时刻的可用人数。</p><dl class="parameters"><template v-for="row in sourceRows" :key="row.path"><dt>{{row.label}}</dt><dd>{{value(row.value)}}</dd></template></dl></template>
    <template v-else><label class="parameter-search">查找全部参数<input v-model="query" type="search" placeholder="如：燃油、signal、来源…" aria-label="搜索单位全部参数"></label><p class="scope-note">共 {{filtered.length}} 项 · 保留原值；含战役过程状态、共享规则及绑定补给点。</p><dl class="parameters all-parameters"><template v-for="row in filtered.slice(0,shown)" :key="row.path"><dt>{{row.label}}<code>{{row.path}}</code></dt><dd><details v-if="value(row.value).length>220"><summary>{{value(row.value).length}}字，展开全文</summary><p>{{value(row.value)}}</p></details><span v-else>{{value(row.value)}}</span></dd></template></dl><p v-if="!filtered.length" role="status">没有匹配参数。</p><button v-if="shown<filtered.length" type="button" @click="shown+=50">再显示50项（已显示{{shown}}／{{filtered.length}}）</button></template>
   </div>

  </template>
 </section>
</template>
<style scoped>
.unit-inspector{font-size:12px;line-height:1.6;border-block:1px solid var(--line,#294553);margin:12px 0;padding:12px 0}.identity{display:flex;gap:10px;align-items:center}.unit-symbol{display:grid;place-items:center;flex:none;width:48px;height:52px;background:#081824;border:1px solid var(--line);border-radius:5px}h3{margin:0;font-size:17px;color:var(--text)}.identity p,.observation{margin:3px 0;color:var(--muted)}.eyebrow{font-size:10px;letter-spacing:.7px;color:var(--muted)}.unit-tabs{display:flex;gap:2px;overflow-x:auto;margin:12px 0 0;border-bottom:1px solid var(--line);padding:0 0 2px}.unit-tabs button{display:flex;flex:none;flex-direction:column;gap:3px;align-items:center;padding:7px 9px;margin:0;border:1px solid transparent;background:transparent;font-size:11px;color:var(--muted);border-radius:5px 5px 0 0}.unit-tabs [aria-selected=true]{background:#16374a;border-color:#33596c;color:#c6f4ff}.unit-tab-body{padding:12px 0;max-height:min(40vh,360px);overflow:auto;scrollbar-gutter:stable}h4{margin:0 0 9px;font-size:12px}h4 small{font-weight:400;color:var(--muted)}.metrics{display:grid;grid-template-columns:1fr 1fr;gap:1px;background:var(--line)}.metrics>div{display:grid;grid-template-columns:20px 1fr;gap:3px 6px;padding:10px 9px;background:var(--panel,#0c2032)}.metrics strong,.metrics small{grid-column:2}.metrics strong{font-size:15px;font-variant-numeric:tabular-nums}.metrics small{font-size:10px;color:var(--muted)}.parameters{display:grid;grid-template-columns:minmax(95px,.85fr) minmax(0,1.15fr);margin:0;gap:0}.parameters dt,.parameters dd{padding:7px 4px;border-bottom:1px solid #29455388;margin:0;overflow-wrap:anywhere}.parameters dt{color:var(--muted)}.parameters dd{font-variant-numeric:tabular-nums}.parameters code{display:block;font-size:10px;color:#8b9eac;overflow-wrap:anywhere}.scope-note{color:var(--muted);font-size:11px;margin:10px 0;line-height:1.7}.table-scroll{overflow-x:auto}table{width:100%;border-collapse:collapse;font-size:11px}caption{text-align:left;color:var(--muted);margin-bottom:7px}th,td{text-align:right;padding:7px 5px;border-bottom:1px solid var(--line);white-space:nowrap}th:first-child{text-align:left}.parameter-search{display:block;color:var(--muted)}input{width:100%;margin-top:6px}.unit-quick-actions{display:flex;flex-wrap:wrap;gap:5px;padding:8px 0}.unit-quick-actions button{display:flex;align-items:center;gap:5px;font-size:11px;margin:0;padding:7px}.unit-quick-actions small{flex-basis:100%;color:var(--muted)}.fortification-state{margin:12px 0}.fortification-state>summary{display:flex;align-items:center;gap:6px;min-height:36px}.fortification-state table{margin-top:8px}details summary{cursor:pointer;color:var(--accent)}button:focus-visible,input:focus-visible,[tabindex]:focus-visible{outline:2px solid var(--accent,#42c6dd);outline-offset:2px}@media(max-width:420px){.unit-tabs button{padding-inline:7px}.metrics strong{font-size:13px}.parameters{grid-template-columns:minmax(90px,.9fr) minmax(0,1.1fr)}}
</style>
